def slug(t): return re.sub(r"[^a-z0-9]+", "-", t.lower()).strip("-")[:60].rstrip("-")
for num, title, status, rel, ctx, opts, dec, cons in A:
    body = [f"# ADR-{num}: {title}", "", f"- **Status:** {status}", f"- **Date:** {DATE}", "- **Deciders:** Tech lead (Phan Cao Khai)", f"- **Related:** {rel}", "",
            "## Context", ctx, "", "## Options considered"] + [f"{i}. {o}" for i, o in enumerate(opts, 1)] + ["", "## Decision", dec, "", "## Consequences", cons, ""]
