(ROOT / "scripts" / ".adr-index.md").write_text("\n".join(f"| [ADR-{n}](adr/ADR-{n}-{slug(t)}.md) | {t} | {s} |" for n, t, s, *_ in A))
print(len(A), "ADRs written")
